def best_average(a: list[int], k: int) -> list[int]:
    import math
    n = len(a)
    prefix = [0] * (n + 1)
    for i, v in enumerate(a):
        prefix[i + 1] = prefix[i] + v

    def worse(i: int, j: int, p: int, q: int) -> bool:
        return (prefix[j] - prefix[i]) * (q - p) < (prefix[q] - prefix[p]) * (j - i)

    hull: list[int] = []
    best_l, best_r = 0, k
    for r in range(k, n + 1):
        x = r - k
        while len(hull) >= 2:
            o = hull[-2]
            b = hull[-1]
            cross = (b - o) * (prefix[x] - prefix[o]) - (prefix[b] - prefix[o]) * (x - o)
            if cross <= 0:
                hull.pop()
            else:
                break
        hull.append(x)
        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if worse(hull[mid], r, hull[mid + 1], r):
                lo = mid + 1
            else:
                hi = mid
        if worse(best_l, best_r, hull[lo], r):
            best_l, best_r = hull[lo], r
    num = prefix[best_r] - prefix[best_l]
    den = best_r - best_l
    g = math.gcd(num, den)
    return [num // g, den // g]
